import json, pathlib, sys
src=pathlib.Path("canonical/astra_runtime/evidence/ASTRA-CAPABILITY-BINDING-PDF-MCP-INSPECTION-001__TOOLS.json")
out=pathlib.Path("canonical/astra_runtime/evidence/ASTRA-CAPABILITY-BINDING-PDF-MCP-INSPECTION-001__SHORTLIST.json")
data=json.loads(src.read_text(encoding="utf-8"))
matches=[]
for server in data.get("results",[]):
    if not server.get("ok"):
        continue
    for tool in server.get("tools",[]):
        text=" ".join(str(tool.get(k) or "") for k in ("name","title","description")).lower()
        if any(word in text for word in ("extract","text","ocr","read","parse")):
            matches.append({
                "url":server.get("url"),
                "protocol_version":server.get("protocol_version"),
                "tool":tool
            })
out.write_text(json.dumps({
    "schema":"PROJECT_BRAIN_PDF_MCP_TOOL_SHORTLIST_V1",
    "source_evidence":str(src),
    "matches":matches,
    "tool_calls_performed":0
},indent=2,sort_keys=True)+"\n",encoding="utf-8")
print("PDF_EXTRACTION_TOOL_SCHEMA_MATCHES",len(matches))
if not matches:
    sys.exit(3)
PY
